#!/bin/bash
# Condense a captured conversation-logs jsonl into a readable summary.
# Usage: condense.sh <path-to-jsonl>
jq -r '
  def trunc(n): if (.|length) > n then .[0:n] + "…[truncated]" else . end;
  . as $e |
  ($e.timestamp // $e.ts // "") as $t |
  if $e.type == "user" and ($e.message.content | type) == "string" then
    "\n[\($t)] USER: " + ($e.message.content | trunc(600))
  elif $e.type == "user" and ($e.message.content | type) == "array" then
    ($e.message.content | map(
      if .type == "text" then "\n[\($t)] USER: " + (.text | trunc(600))
      elif .type == "tool_result" then "\n[\($t)] TOOL_RESULT: " + ((.content | tostring) | trunc(400))
      else empty end
    ) | join(""))
  elif $e.type == "assistant" then
    ($e.message.content | map(
      if .type == "text" then "\n[\($t)] ASSISTANT: " + (.text | trunc(600))
      elif .type == "tool_use" then "\n[\($t)] TOOL_USE(\(.name)): " + ((.input|tostring) | trunc(300))
      else empty end
    ) | join(""))
  else empty end
' "$1" 2>/dev/null

