#!/bin/bash
# Condense a captured conversation-logs jsonl into a readable summary.
# Usage: condense.sh <path-to-jsonl>
jq -r '
  def trunc(n): if (.|length) > n then .[0:n] + "…[truncated]" else . end;
  . as $e |
  ($e.timestamp // "") as $t |
  if ($e.type == "user" or $e.type == "assistant") then
    (
      if ($e.message.content | type) == "string" then
        [{type:"text", text: $e.message.content}]
      else
        $e.message.content
      end
    ) as $parts |
    ($parts | map(
      if .type == "text" then "\n[\($t)] \($e.type|ascii_upcase): " + (.text | trunc(500))
      elif .type == "tool_use" then "\n[\($t)] TOOL_USE(\(.name)): " + ((.input|tostring) | trunc(250))
      elif .type == "tool_result" then "\n[\($t)] TOOL_RESULT: " + ((.content|tostring) | trunc(300))
      else empty end
    ) | join(""))
  else empty end
' "$1" 2>/dev/null

